from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','madhus-wish','Madhu\'s Wish',
 ('A tree that grants wishes','Madhu loves food. After he shares his lunch with a hungry old man, the man tells him a tree will grant any wish. Madhu asks for different kinds of food and nothing else. Soon he learns why water matters. This story is by Sudha Murty. In this chapter you will follow the story, sort foods into groups, describe people with quality words, join sentences with and and but, and give reasons with because.'),
 [('Madhu and the old man',['Madhu loved food and wanted to eat different foods and snacks all the time.','Every noon he sat under a banyan tree and ate his lunch.','One day an old man came by. Madhu felt sorry for him and shared his food.','The old man was so pleased that he told Madhu to wish for anything from the tree, and it would be granted.']),
  ('The wish',['Madhu closed his eyes and asked for different types of food, and nothing else.','A voice from the tree asked him to think it over, but Madhu said Nothing else without thinking.','He asked for laddoos and a basket of laddoos appeared. When he was bored he asked for fruits, and then for savouries.','Soon he got hiccups and wanted water, but there was food everywhere and no water.','The tree reminded him that he had asked only for food, not water.']),
  ('What Madhu learned',['Madhu tried sharbat, kheer and badam milk, but his hiccups only got louder.','He prayed that all the food disappear and that he get water instead. The tree asked if he was sure.','He said that now he knew how important water is, because no other drink can replace it.','A jug of water appeared. He drank it and his hiccups stopped.','The story teaches us to think before we wish and to value simple things like water.']),
  ('New words',['Forever means for all time. Immediately means at once, without waiting.','Appeared means came into sight. Disappear means go out of sight.','Savouries are salty snacks like samosas, kachoris and vadas.','Hiccups are sudden little sounds in the throat. Thirsty means needing water. Replace means to put one thing in place of another.']),
  ('Sorting words into groups',['Madhu enjoyed fruits, sweets and salty snacks.','Fruits are banana, melon, guava and jackfruit.','Sweets are kheer and laddoo. Salty snacks are kachori, potato chips, vada and samosa.','Putting things in groups makes it easier to remember them.']),
  ('Quality words',['Words that tell what someone is like are called quality words.','Madhu shared his food, so he is kind. He wanted to eat everything, so he is greedy. The old man gave a special gift, so he is generous.','Pramod does not share his toys, so he is selfish. The woman who saved a boy is brave.','Advait lies in bed doing nothing, so he is lazy. Prerna greets everyone, so she is polite.']),
  ('Joining sentences with and, but and because',['We can join two sentences that say similar things with and. Sam and Pratham are watching television.','Aman has a pen, a pencil and an eraser uses and to join three things.','We use but when two ideas are different. Sam works in the afternoon but Pratham works at night.','We use because to give a reason. Madhu shared his food because he felt sorry for the old man.'])],
 [('Join with and: Anita plays volleyball. Anju plays volleyball.',[('Both sentences say the same kind of thing.','The same action is done by two people.'),('We join the people with and.','And joins things that go together.'),('So: Anita and Anju play volleyball.','The verb becomes play because there are two girls.')]),
  ('Join with but: Dolma wants a new comic book. She has spent all her pocket money on sweets.',[('The two ideas work against each other.','She wants something but cannot buy it.'),('We use but.','But shows a difference.'),('So: Dolma wants a new comic book but she has spent all her pocket money on sweets.','The sentence now makes one idea.')]),
  ('Which quality word fits: Pramod does not share his toys with anyone.',[('Think about what Pramod does.','He keeps everything to himself.'),('The word for that is selfish.','Selfish is the opposite of generous.'),('So: He is selfish.','Choose from brave, polite, selfish, lazy.')])],
 ('Tell the story of Madhu and the wishing tree and say what he learned.',['Madhu shared food with the old man','He wished for only food','He got hiccups and had no water','He learned the importance of water'],['Madhu wished for gold','The tree gave him water at first','Madhu did not share']),
 ['Madhu shared his food and got a wish from the tree.','He wished for food only, so there was no water.','Water cannot be replaced by any other drink.','Quality words describe people: kind, greedy, brave, selfish.','And joins, but shows a difference and because gives a reason.'],
 [M('1',1,'What did Madhu enjoy most?','Eating different foods',[('Playing games','The story is about food'),('Reading','Not in the story')],'He loved food.'),
  M('2',1,'Why did the old man give Madhu a wish?','Madhu shared his food',[('Madhu paid him','Madhu shared'),('The tree was angry','The tree granted the wish')],'Madhu was kind.'),
  M('3',1,'Why did the tree ask Madhu to think it over?','So he would wish carefully',[('The tree was sleepy','It wanted him to think'),('The tree did not like food','Not true')],'The tree gave him a chance to think.'),
  M('4',1,'Why did Madhu need water?','He had hiccups and was thirsty',[('He was cold','Hiccups and thirst'),('He was sleepy','Not the reason')],'He had asked for food only.'),
  M('5',2,'Which is a savoury?','Samosa',[('Kheer','Kheer is a sweet'),('Banana','Banana is a fruit')],'A samosa is a salty snack.'),
  M('6',2,'Which is a sweet?','Laddoo',[('Vada','Vada is salty'),('Guava','Guava is a fruit')],'A laddoo is sweet.'),
  M('7',2,'Madhu shared his food. He is ___.','kind',[('greedy','Sharing is not greedy'),('lazy','Not about work')],'Sharing is kind.'),
  M('8',2,'Which word fits: The woman saved the boy from the robber. She is ___.','brave',[('lazy','Saving is brave'),('selfish','Saving shows courage')],'She is brave.'),
  M('9',2,'Which word joins: Aman has a pen ___ a pencil.','and',[('but','But shows a difference'),('because','Because gives a reason')],'And joins things together.'),
  M('10',2,'Which word joins: I like cartoons ___ my sister likes movies.','but',[('and','The ideas are different'),('because','No reason is given')],'But shows the difference.'),
  F('11',2,'No other drink can replace water, said Madhu.',True,'He said so after the hiccups.'),
  S('12',3,'Who wrote the story Madhu\'s Wish?',['sudha murty','sudha murthy'],'The story is by Sudha Murty.')],
 keep=['hiccups','savouries'])
